84	
85	/// Champion of the Parish gets a +1/+1 counter when another Human enters.
86	#[test]
87	fn champion_of_the_parish_counter_on_human_etb() {
88	    let reg = registry();
89	    let mut state = game_at_step(Step::PrecombatMain, P0);
90	
91	    let champion = named_creature(&mut state, &reg, "Champion of the Parish", P0);
92	
93	    // Another Human enters the battlefield under our control.
94	    let human = named_creature(&mut state, &reg, "Unruly Mob", P0);
95	    state.events.push(mtg_engine::events::GameEvent::EnteredBattlefield {
96	        object: human,
97	        controller: P0,
98	    });
99	    triggers::process_triggers(&mut state, &reg);
100	
101	    let counters = *state.get_object(champion).unwrap()
102	        .counters.get(&CounterType::PlusOnePlusOne).unwrap_or(&0);
103	    assert_eq!(counters, 1, "Champion should get a +1/+1 counter");
104	}
105	
