108	fn champion_of_the_parish_no_counter_on_non_human() {
109	    let reg = registry();
110	    let mut state = game_at_step(Step::PrecombatMain, P0);
111	
112	    let champion = named_creature(&mut state, &reg, "Champion of the Parish", P0);
113	
