115	    let vampire = named_creature(&mut state, &reg, "Rakish Heir", P0);
116	    state.events.push(mtg_engine::events::GameEvent::EnteredBattlefield {
117	        object: vampire,
118	        controller: P0,
119	    });
120	    triggers::process_triggers(&mut state, &reg);
121	
122	    let counters = *state.get_object(champion).unwrap()
123	        .counters.get(&CounterType::PlusOnePlusOne).unwrap_or(&0);
124	    assert_eq!(counters, 0, "Champion should NOT trigger on non-Human");
125	}
